/* ---------- Details panel ---------- */
/* a run's properties in sections that fold, each value changed in place from a small menu. Its content sits 16px from every
   edge (owner, 18 Nov): the run's kind, its name and the copy button's glyph on the head's line; each section's name is a
   label on the content's left edge, in the small muted label type with room above it and its chevron after the words; the
   keys start on that edge too, and the values share one column, a value you can change lining up by its words, its hover
   box reaching out round them. The card follows its sections as they fold, so it keeps no room for a shut one */
.dtp{padding:16px 16px 8px;display:flex;flex-direction:column}
.dtp-h{display:flex;align-items:center;gap:8px;min-height:28px;font-size:13.5px}
/* the kind is metadata, so it is muted, never coloured */
.dtp-h .ft{flex:none;color:var(--dm-muted)}
.dtp-h b{flex:1;min-width:0;font-weight:500;line-height:20px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* the copy button's glyph ends on the content's edge, its hover circle reaching out round it; done, the glyph is the vivid
   green tick, in place */
.dtp-cp{width:28px;height:28px;margin-right:-8px}
.dtp .ib.copied{color:var(--dm-ok-mark)!important}
@media (hover:hover) and (pointer:fine){.dtp .ib.copied:hover{color:var(--dm-ok-mark)!important}}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.dtp :is(.ib,.pill):active,:root[data-style="clean"] .dtp .ib:active,:root [data-style="clean"] .dtp .ib:active,:root [data-style="clean"].dtp .ib:active{transform:none}
.dtp-sec{display:flex;flex-direction:column;transition:padding var(--dm-t) var(--dm-ease)}
/* with the last section shut, its label is the panel's last line, and it too sits 16px from the foot */
.dtp-sec:not(:has(~.dtp-sec)):has(>.fold.shut){padding-bottom:3px}
.dtp-sh{display:inline-flex;align-self:flex-start;align-items:center;gap:4px;height:24px;margin:12px -6px 2px;padding:0 6px;border-radius:var(--dm-r-sm);font-size:11.5px;color:var(--dm-muted);text-align:left;transition:color var(--dm-t-fast),background-color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dtp-sh:hover{color:var(--dm-fg);background:var(--dm-row)}}
.dtp-sh svg{transition:transform .4s var(--dm-ease);transform:rotate(90deg)}
.dtp-sh[aria-expanded="false"] svg{transform:none}
.dtp-rows{display:flex;flex-direction:column}
/* a section's rows settle 4px as it folds open, and lift away as it folds shut */
.dtp .fold .dtp-rows{transition:transform var(--dm-t) var(--dm-ease)}
.dtp .fold.shut .dtp-rows{transform:translateY(-4px)}
.dtp-r{display:grid;grid-template-columns:84px minmax(0,1fr);align-items:center;min-height:32px;font-size:13px;position:relative}
.dtp-r .k{color:var(--dm-muted)}
.dtp-v{display:inline-flex;align-items:center;gap:7px;justify-self:start;height:28px;padding:0 var(--dm-s-2);margin-left:-8px;border-radius:var(--dm-r-sm);transition:background .2s;color:var(--dm-fg)}
/* a value that starts with a photo sits as far from the box's left edge as from its top and bottom (owner, 10 Nov) */
.dtp-v:has(>.av:first-child){padding:0 6px 0 4px;margin-left:-4px}
:where([data-c]) button.dtp-v[aria-expanded="true"]{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){:where([data-c]) button.dtp-v:hover{background:var(--dm-row)}}
.dtp-v .av{width:20px;height:20px;font-size:9.5px}
.dtp-v>svg{color:var(--dm-muted)}
.dtp-v.flash{animation:dtpf .9s var(--dm-ease)}
@keyframes dtpf{30%{background:var(--dm-accent-bg)}}
.dtp-tags{display:flex;gap:var(--dm-s-1);align-items:center;flex-wrap:wrap}
.dtp-add{width:20px;height:20px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));display:grid;place-items:center;color:var(--dm-muted);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);transition:color var(--dm-t-fast),background-color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dtp-add:hover{color:var(--dm-fg);background:var(--dm-row)}}
.dtp .mi .av{width:20px;height:20px;font-size:9.5px}
.dtp .pop{min-width:180px}
/* Clean (owner, 18 Nov): the add button is a circle like Clean's other small controls, and hovers and fades take Clean's
   calm 220ms */
:root[data-style="clean"] .dtp-add,:root [data-style="clean"] .dtp-add,:root [data-style="clean"].dtp-add{border-radius:50%;box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] :is(.dtp-sh,.dtp-v,.dtp-add),:root [data-style="clean"] :is(.dtp-sh,.dtp-v,.dtp-add),:root [data-style="clean"]:is(.dtp-sh,.dtp-v,.dtp-add){transition:color var(--dm-t-fast) var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease)}
/* its ghost controls, a section's toggle and a value's menu button, are pills, as every Clean control is (owner, 18 Nov) */
:root[data-style="clean"] :is(.dtp-sh,.dtp-v),:root [data-style="clean"] :is(.dtp-sh,.dtp-v),:root [data-style="clean"]:is(.dtp-sh,.dtp-v){border-radius:var(--dm-r-pill)}
/* Clean is ruled (owner, 22 Nov: "a divider under the heading, more dividers"): the head is Clean's off-white strip over a
   hairline, as Task table's is, and a hairline runs edge to edge between the sections, each section's label sitting 12px under its line as the first one sits under the head's */
:root[data-style="clean"] .dtp,:root [data-style="clean"] .dtp,:root [data-style="clean"].dtp{padding-top:0}
:root[data-style="clean"] .dtp-h,:root [data-style="clean"] .dtp-h,:root [data-style="clean"].dtp-h{margin:0 -16px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .dtp-sec+.dtp-sec,:root [data-style="clean"] .dtp-sec+.dtp-sec,:root [data-style="clean"].dtp-sec+.dtp-sec{margin:8px -16px 0;padding-left:16px;padding-right:16px;border-top:1px solid var(--dm-line)}

DM.def('details-panel', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{link}', I('link','xs')).replace(/\{chev\}/g, I('chev-r','xs')).replace('{chevd}', I('chev-d','xs')).replace('{plus}', I('plus','xs'))
    .replace(/\{avm\}/g, AV('MK','var(--dm-av-l)')).replace('{avj}', AV('JO','var(--dm-av-m)')).replace('{ava}', AV('DA','var(--dm-av-b)'));
  const flash = el => { el.classList.remove('flash'); void el.offsetWidth; el.classList.add('flash'); };
  $$('.pop', r).forEach(pp => $('.dtp', r).appendChild(pp));
  $$('.dtp-sh', r).forEach(b => b.onclick = () => { const f = b.nextElementSibling, open = f.classList.toggle('shut') === false; b.setAttribute('aria-expanded', open); });
  $$('.dtp-pst .mi', r).forEach(m => m.addEventListener('click', () => { const v = $('.dtp-stat', r); $('.dot', v).style.color = m.dataset.col; swap($('span:last-child', v), m.dataset.s); flash(v); }));
  $$('.dtp-pow .mi', r).forEach(m => m.addEventListener('click', () => { const v = $('.dtp-own', r); const av = $('.av', v); av.textContent = m.dataset.i; av.style.background = m.dataset.col; av.style.color = m.dataset.col.replace(')', '-ink)'); enter(av); swap($('span:last-child', v), m.dataset.o); flash(v); }));
  const cost = { Opus:[184200, 2.76], Sonnet:[184200, .55], Haiku:[184200, .15] }; let cc = 0, ct = 0;
  const setM = m => { tween(ct, cost[m][0], 800, v => { ct = v; $('.dtp-tok', r).textContent = Math.round(v).toLocaleString('en-US'); }); tween(cc, cost[m][1], 800, v => { cc = v; $('.dtp-cost', r).textContent = '$' + v.toFixed(2); }); };
  $$('.dtp-pmo .mi', r).forEach(m => m.addEventListener('click', () => { const v = $('.dtp-mo', r); swap(v, m.dataset.m); flash(v.parentElement); setM(m.dataset.m); }));
  const labels = [['Q4','y'],['A/B test','t'],['Urgent','r']]; let li = 0;
  $('.dtp-add', r).onclick = e => { if (li >= labels.length) return; const t = html(`<span class="tag ${labels[li][1]}">${labels[li][0]}</span>`); e.currentTarget.before(t); enter(t); li++; };
  const cp = $('.dtp-cp', r); cp.onclick = () => copied(cp, 'run_8f2a');
  // the run's tokens and cost count up once it has entered, unless a model you picked is counting already
  c.later(700, () => { if (!ct) setM('Opus'); });
});
